try{const saved=localStorage.getItem(KEY);if(saved)state=validateProject(JSON.parse(saved));}catch(e){console.warn(e.message);$('storageStatus').textContent='Saved project could not be restored. Open a backup.';}
active=state.routes[0].id;const current=()=>state.routes.find(r=>r.id===active),direction=()=>$('profileDirection').value;
