function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('storageStatus').textContent='Saved locally';}catch{$('storageStatus').textContent='Browser storage unavailable. Save a project file.';}}
function stopPlayback(){clearInterval(playTimer);playTimer=null;$('playTrip').textContent='▶ Play on map';}
function clearPreview(){preview=null;$('preview').hidden=true;stopPlayback();if(playMarker)map.removeLayer(playMarker);playMarker=null;}
function cancelBuild(){buildToken++;controller?.abort();controller=null;$('buildRoute').disabled=false;}
function changed(invalidate=false){if(invalidate){current().paths=null;cancelBuild();}clearPreview();save();renderNav();renderStats();}
function renderNav(){$('routeCount').textContent=state.routes.length;$('routes').innerHTML=state.routes.map(r=>`<button class="routeitem ${r.id===active?'active':''}" data-route="${esc(r.id)}" ${r.id===active?'aria-current="page"':''}><span class="routeicon" aria-hidden="true">⌁</span><span><strong>${esc(r.name||'Untitled route')}</strong><small>${r.points.length} points · ${r.outboundCount+r.returnCount} trips</small></span></button>`).join('');$('routeNumber').textContent=String(state.routes.findIndex(r=>r.id===active)+1).padStart(2,'0');}
let map,layers;try{map=L.map('map').setView([18.12,120.56],11);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);layers=L.layerGroup().addTo(map);map.on('click',e=>addPoint([e.latlng.lng,e.latlng.lat]));}catch{$('map').textContent='Map could not load. Reload the page.';}
function pointName(p,i,r){return p.kind==='stop'?p.name||'Stop':i===0?'Start':i===r.points.length-1?'Destination':'Via '+i;}
function renderMap(fit=false){if(!map)return;layers.clearLayers();const r=current();if(r.paths){L.polyline(r.paths.return.coords.map(p=>[p[1],p[0]]),{color:'#7a6298',weight:5,opacity:.65,dashArray:'7 7'}).addTo(layers);L.polyline(r.paths.outbound.coords.map(p=>[p[1],p[0]]),{color:'#175947',weight:4}).addTo(layers);}else if(r.points.length>1)L.polyline(r.points.map(p=>[p.coord[1],p.coord[0]]),{color:'#789170',weight:2,dashArray:'5 7'}).addTo(layers);r.points.forEach((p,i)=>{L.marker([p.coord[1],p.coord[0]],{draggable:true,icon:L.divIcon({className:'',html:`<span class="pin ${p.kind==='stop'?'stop':''}">${p.kind==='stop'?'◷':i===0?'A':i===r.points.length-1?'B':i}</span>`,iconSize:[30,30],iconAnchor:[15,15]})}).addTo(layers).bindTooltip(document.createTextNode(p.name||pointName(p,i,r))).on('dragend',e=>{const ll=e.target.getLatLng();p.coord=[ll.lng,ll.lat];changed(true);renderPoints();renderMap();});});$('maphint').textContent=mode==='stop'?'Click a place to add a timed stop':r.points.length===0?'Click the map to place your starting point':r.points.length===1?'Click to choose your destination':'Click to extend the route · drag a marker to move it';if(fit){const coords=r.paths?r.paths.outbound.coords:r.points.map(p=>p.coord);if(coords.length>1)map.fitBounds(coords.map(p=>[p[1],p[0]]),{padding:[40,40],maxZoom:15});else if(coords.length)map.setView([coords[0][1],coords[0][0]],14);}}
function renderPoints(){const r=current();$('waypoints').innerHTML=r.points.map((p,i)=>`<div class="waypoint"><span>${p.kind==='stop'?'◷':String(i+1).padStart(2,'0')}</span><div><strong>${esc(pointName(p,i,r))}</strong><small>${p.coord[1].toFixed(5)}, ${p.coord[0].toFixed(5)}</small></div><button data-remove="${p.id}" aria-label="Remove ${esc(pointName(p,i,r))}">×</button></div>`).join('');const stops=r.points.filter(p=>p.kind==='stop');$('stopCount').textContent=stops.length+' stop'+(stops.length===1?'':'s');$('stops').innerHTML=stops.length?stops.map(p=>`<div class="stoprow"><div class="stoprowhead"><input aria-label="Stop name" data-stop-name="${p.id}" value="${esc(p.name)}" maxlength="80"><button class="quiet" data-remove="${p.id}" aria-label="Remove ${esc(p.name)}">×</button></div><div class="stoprowbody"><label>Duration (seconds)<input type="number" min="0" max="7200" step="1" data-stop-duration="${p.id}" value="${p.duration}"></label><button data-random="${p.id}" title="Choose 30 to 300 seconds">⚄ Random time</button></div></div>`).join(''):'<div class="emptystops"><span aria-hidden="true">◷</span><strong>A little traffic. A quick errand.</strong><p>Add stops to make the journey feel real.</p><button id="emptyAddStop">+ Add a stop on the map</button></div>';}
function setMode(m){mode=m;for(const v of ['waypoint','stop']){$(v+'Mode').classList.toggle('selected',v===m);$(v+'Mode').setAttribute('aria-pressed',v===m);}renderMap();}
function addPoint(coord){const r=current();if(!validCoord(coord)){toast('Enter valid latitude and longitude.',true);return;}if(r.points.length>=100){toast('Up to 100 points per route.',true);return;}const p={id:uid(),coord,kind:mode==='stop'?'stop':'waypoint',name:mode==='stop'?'Stop '+(r.points.filter(x=>x.kind==='stop').length+1):'',duration:60};if(mode==='stop'){if(r.points.length<2){toast('Place a start and destination before adding a stop.',true);return;}let index=r.points.length-1;if(r.paths){const g=geometry(r.paths.outbound.coords),snap=project(g,coord);p.coord=snap.coordinate;const along=r.paths.outbound.snapped.map(x=>project(g,x).along);index=along.findIndex((a,i)=>i>0&&a>=snap.along);}else{const g=geometry(r.points.map(x=>x.coord)),snap=project(g,coord);index=g.cumulative.findIndex((a,i)=>i>0&&a>=snap.along);}if(index<1)index=r.points.length-1;r.points.splice(index,0,p);}else r.points.push(p);additions.push(p.id);changed(true);renderPoints();renderMap();$('routeStatus').textContent='Route changed. Build the road route to update both directions.';}
async function routeRequest(points,signal){const url=state.server.replace(/\/$/,'')+'/route/v1/driving/'+points.map(p=>p.coord.join(',')).join(';')+'?overview=full&geometries=geojson&steps=false';const response=await fetch(url,{signal});if(!response.ok)throw Error('OSRM returned HTTP '+response.status+'. Try again or use another server.');const data=await response.json();if(data.code!=='Ok'||!data.routes?.length||data.waypoints?.length!==points.length)throw Error(data.message||'No drivable route connects these points. Move markers closer to roads.');const path=data.routes[0];geometry(path.geometry.coordinates);return {coords:path.geometry.coordinates,snapped:data.waypoints.map(w=>w.location),osrmDistance:path.distance,osrmDuration:path.duration,fetchedAt:new Date().toISOString(),server:state.server};}
async function build(){const r=current();if(r.points.length<2){toast('Place at least a start and destination.',true);return;}cancelBuild();const token=buildToken,routeId=r.id,snapshot=structuredClone(r.points);controller=new AbortController();const signal=controller.signal,timeout=setTimeout(()=>{if(token===buildToken)controller?.abort();},45000);$('buildRoute').disabled=true;$('routeStatus').textContent='Finding roads for outbound and return journeys…';try{validateServer(state.server);const outbound=await routeRequest(snapshot,signal);const inbound=await routeRequest([...snapshot].reverse(),signal);if(token!==buildToken||routeId!==active)return;r.paths={outbound,return:inbound};changed();renderMap(true);$('routeStatus').textContent='Road route ready · both directions checked with OSRM.';toast('Both directions are ready.');}catch(e){if(token!==buildToken)return;r.paths=null;renderStats();$('routeStatus').textContent=e.name==='AbortError'?'Routing timed out. Try again or use another server.':e.message;toast($('routeStatus').textContent,true);}finally{clearTimeout(timeout);if(token===buildToken){controller=null;$('buildRoute').disabled=false;}}}
function getStops(r,dir){const path=r.paths[dir],g=geometry(path.coords),ordered=dir==='outbound'?r.points:[...r.points].reverse();let min=0;const stops=[];ordered.forEach((p,i)=>{const snap=project(g,path.snapped[i],min);min=snap.along;if(snap.distance>30)throw Error('Saved waypoint does not match route geometry. Rebuild the route.');if(p.kind==='stop')stops.push({id:p.id,name:p.name,along:snap.along,duration:p.duration});});return stops;}
const duration=s=>s>=3600?`${Math.floor(s/3600)}h ${Math.round(s%3600/60)}m`:`${Math.floor(s/60)}m ${Math.round(s%60)}s`;
function renderStats(){const r=current();$('tripTotal').textContent=(Number(r.outboundCount)+Number(r.returnCount))+' separate recordings';if(!r.paths){for(const id of ['distanceStat','durationStat','sampleStat'])$(id).textContent='—';return;}try{const sim=simulate({coords:r.paths[direction()].coords,profile:r.profiles[direction()],stops:getStops(r,direction()),start:r[direction()+'Start']+'+08:00',seed:r.seed});$('distanceStat').textContent=(sim.distance/1000).toFixed(2)+' km';$('durationStat').textContent=duration(sim.recordedDuration);$('sampleStat').textContent=sim.rows.length.toLocaleString();}catch{$('durationStat').textContent='Check speeds';$('sampleStat').textContent='—';$('distanceStat').textContent=(geometry(r.paths[direction()].coords).length/1000).toFixed(2)+' km';}}
function render(){const r=current();renderNav();$('routeName').value=r.name;for(const id of ['outboundCount','returnCount','outboundStart','returnStart','spacingHours','format','speedVariation','stopVariation','seed','graphRange'])$(id).value=r[id];$('osrmServer').value=state.server;for(const id of ['speedVariation','stopVariation'])$(id+'Label').textContent=r[id];renderPoints();renderProfile();renderMap(true);renderStats();$('routeStatus').textContent=r.paths?'Road route ready · both directions checked with OSRM.':'Start with two places. Roads connect them automatically.';}
const plot={left:40,right:626,top:16,bottom:191};
function graphPoint(e){const svg=$('speedGraph'),pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const xy=pt.matrixTransform(svg.getScreenCTM().inverse()),r=current();return {t:Math.max(0,Math.min(r.graphRange,Math.round((xy.x-plot.left)/(plot.right-plot.left)*r.graphRange/5)*5)),v:Math.max(0,Math.min(160,Math.round((plot.bottom-xy.y)/(plot.bottom-plot.top)*160)))};}
function renderGraph(){const r=current(),p=[...r.profiles[direction()]].sort((a,b)=>a.t-b.t),range=r.graphRange,x=t=>plot.left+t/range*(plot.right-plot.left),y=v=>plot.bottom-v/160*(plot.bottom-plot.top);let html='';for(let v=0;v<=160;v+=40)html+=`<line x1="${plot.left}" x2="${plot.right}" y1="${y(v)}" y2="${y(v)}" stroke="#e4eadd"/><text x="30" y="${y(v)+4}" text-anchor="end">${v}</text>`;const gridStep=range<=600?30:Math.ceil(range/600)*30;for(let t=0;t<=range;t+=gridStep){html+=`<line x1="${x(t)}" x2="${x(t)}" y1="${plot.top}" y2="${plot.bottom}" stroke="#eef2e9"/>`;if(t%(gridStep*(range<=300?2:3))===0||t===range)html+=`<text x="${x(t)}" y="214" text-anchor="middle">${t}s</text>`;}const visible=p.filter(a=>a.t<=range),last=visible.at(-1),next=p.find(a=>a.t>range),edge=next?last.v+(next.v-last.v)*(range-last.t)/(next.t-last.t):last.v;const points=visible.map(a=>`${x(a.t)},${y(a.v)}`).join(' ')+` ${x(range)},${y(edge)}`;html+=`<polygon points="${plot.left},${plot.bottom} ${points} ${plot.right},${plot.bottom}" fill="#edf3e8" opacity=".8"/><polyline points="${points}" fill="none" stroke="#175947" stroke-width="2.5"/>`;p.forEach((a,i)=>{if(a.t<=range)html+=`<circle class="handle" data-index="${current().profiles[direction()].indexOf(a)}" cx="${x(a.t)}" cy="${y(a.v)}" r="7"><title>${a.t} seconds, ${a.v} km/h</title></circle>`;});$('speedGraph').innerHTML=html;}
function renderProfile(){const p=current().profiles[direction()];$('speedPoints').innerHTML=p.map((a,i)=>`<tr><td><input aria-label="Time for speed point ${i+1}" data-time="${i}" type="number" min="0" max="7200" step="5" value="${a.t}" ${i===0?'readonly':''}></td><td><input aria-label="Speed for point ${i+1}" data-speed="${i}" type="number" min="0" max="160" value="${a.v}"></td><td><button data-delete-speed="${i}" aria-label="Remove speed point ${i+1}" ${i===0?'disabled':''}>×</button></td></tr>`).join('');renderGraph();}
function commitProfile(){current().profiles[direction()]=normalizeProfile(current().profiles[direction()]);changed();renderProfile();}
$('speedGraph').addEventListener('pointerdown',e=>{const i=e.target.dataset.index;if(i!==undefined){const t=current().profiles[direction()][Number(i)].t;current().profiles[direction()]=normalizeProfile(current().profiles[direction()]);drag={index:current().profiles[direction()].findIndex(a=>a.t===t),id:e.pointerId};$('speedGraph').setPointerCapture(e.pointerId);e.preventDefault();}else{const point=graphPoint(e),p=current().profiles[direction()];if(p.some(a=>a.t===point.t)){toast('A point already exists here. Drag it or edit the table.');return;}p.push(point);commitProfile();}});
