$('speedPoints').addEventListener('change',e=>{const el=e.target,i=Number(el.dataset.time??el.dataset.speed),p=current().profiles[direction()],key=el.dataset.time!==undefined?'t':'v',old=p[i][key];p[i][key]=el.valueAsNumber;try{if(key==='t'&&p[i].t>7200)throw Error('Speed point times must be within 7,200 seconds.');commitProfile();}catch(err){p[i][key]=old;renderProfile();toast(err.message,true);}});
$('speedPoints').addEventListener('click',e=>{const b=e.target.closest('[data-delete-speed]');if(b&&Number(b.dataset.deleteSpeed)>0){current().profiles[direction()].splice(Number(b.dataset.deleteSpeed),1);commitProfile();}});
$('addSpeedPoint').onclick=()=>{const r=current(),p=r.profiles[direction()],point={t:p.at(-1).t+30,v:p.at(-1).v};if(point.t>7200){toast('Keep speed points within 7,200 seconds.',true);return;}p.push(point);r.graphRange=Math.max(r.graphRange,point.t);$('graphRange').value=r.graphRange;commitProfile();};$('resetSpeed').onclick=()=>{current().profiles[direction()]=defaultProfile();current().graphRange=300;$('graphRange').value=300;commitProfile();};$('copyProfile').onclick=()=>{current().profiles[direction()==='outbound'?'return':'outbound']=structuredClone(current().profiles[direction()]);changed();toast('Profile copied to the other direction.');};$('profileDirection').onchange=()=>{stopPlayback();renderProfile();renderStats();};
function addRoute(){if(state.routes.length>=50){toast('Up to 50 routes per project.',true);return;}cancelBuild();clearPreview();const r=newRoute('Route '+(state.routes.length+1));state.routes.push(r);active=r.id;additions=[];save();render();$('routeName').focus();}$('addRoute').onclick=addRoute;$('addRouteWide').onclick=addRoute;$('routes').onclick=e=>{const b=e.target.closest('[data-route]');if(b){cancelBuild();clearPreview();active=b.dataset.route;additions=[];render();}};$('routeName').oninput=e=>{current().name=e.target.value;changed();};$('deleteRoute').onclick=()=>{if(!confirm('Delete “'+current().name+'” and its settings?'))return;cancelBuild();clearPreview();state.routes=state.routes.filter(r=>r.id!==active);if(!state.routes.length)state.routes.push(newRoute('Route 1'));active=state.routes[0].id;save();render();};
$('waypointMode').onclick=()=>setMode('waypoint');$('stopMode').onclick=()=>setMode('stop');$('stops').addEventListener('click',e=>{if(e.target.closest('#emptyAddStop')){setMode('stop');$('map').scrollIntoView({behavior:'smooth',block:'center'});}const b=e.target.closest('[data-random]');if(b){current().points.find(p=>p.id===b.dataset.random).duration=30+Math.floor(Math.random()*271);changed();renderPoints();}});for(const id of ['waypoints','stops'])$(id).addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(b){current().points=current().points.filter(p=>p.id!==b.dataset.remove);changed(true);renderPoints();renderMap();}});
$('stops').addEventListener('change',e=>{const id=e.target.dataset.stopName??e.target.dataset.stopDuration;if(!id)return;const p=current().points.find(p=>p.id===id);if(e.target.dataset.stopName!==undefined){p.name=e.target.value;changed();renderMap();return;}const n=e.target.valueAsNumber;if(!Number.isFinite(n)||n<0||n>7200){toast('Stop duration must be between 0 and 7,200 seconds.',true);renderPoints();return;}p.duration=n;changed();});$('undoPoint').onclick=()=>{const r=current();let id;while(additions.length&&!id){const c=additions.pop();if(r.points.some(p=>p.id===c))id=c;}if(id)r.points=r.points.filter(p=>p.id!==id);else r.points.pop();changed(true);renderPoints();renderMap();};$('manualPoint').onclick=()=>addPoint([$('manualLng').valueAsNumber,$('manualLat').valueAsNumber]);$('fitRoute').onclick=()=>renderMap(true);$('buildRoute').onclick=build;
$('osrmServer').onchange=e=>{try{validateServer(e.target.value);state.server=e.target.value.replace(/\/$/,'');for(const r of state.routes)r.paths=null;changed(true);renderMap();toast('Server changed. Rebuild routes.');}catch(err){toast(err.message,true);e.target.value=state.server;}};
for(const id of ['outboundCount','returnCount','outboundStart','returnStart','spacingHours','format','speedVariation','stopVariation','seed'])$(id).addEventListener('change',e=>{const r=current(),old=r[id];r[id]=['outboundStart','returnStart','format'].includes(id)?e.target.value:e.target.valueAsNumber;try{validateSettings(r);changed();}catch(err){r[id]=old;e.target.value=old;toast(err.message,true);}});for(const id of ['speedVariation','stopVariation'])$(id).addEventListener('input',e=>{$(id+'Label').textContent=e.target.value;current()[id]=e.target.valueAsNumber;changed();});$('graphRange').onchange=e=>{const n=e.target.valueAsNumber;if(!Number.isFinite(n)||n<60||n>7200){e.target.value=current().graphRange;toast('Graph range must be 60–7,200 seconds.',true);return;}current().graphRange=n;save();renderGraph();};
function download(content,name,type='application/octet-stream'){const url=URL.createObjectURL(content instanceof Blob?content:new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}$('saveProject').onclick=()=>{download(JSON.stringify(state,null,2),'ligtas-trip-studio-project.json','application/json');toast('Project downloaded with geometry and settings.');};$('importProject').onclick=()=>$('projectFile').click();$('projectFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>30*1024*1024)throw Error('Project files must be under 30 MB.');const incoming=validateProject(JSON.parse(await file.text()));cancelBuild();clearPreview();state=incoming;active=state.routes[0].id;additions=[];save();render();toast('Project opened.');}catch(err){toast(err.message,true);}finally{e.target.value='';}};
const slug=s=>s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,50)||'route';
async function generate(r,onProgress=()=>{}){if(document.querySelector('[aria-invalid="true"]'))throw Error('Correct the highlighted input before generating.');validateSettings(r);if(!r.paths)throw Error('Build the road route for “'+r.name+'” before generating.');if(r.outboundCount+r.returnCount===0)throw Error('Set at least one trip for “'+r.name+'”.');const entries=[];let rowsTotal=0,index=0;for(const dir of ['outbound','return'])for(let i=0;i<r[dir+'Count'];i++){const start=new Date(Date.parse(r[dir+'Start']+'+08:00')+i*r.spacingHours*3600000).toISOString(),seed=(r.seed+index*104729)>>>0,sim=simulate({coords:r.paths[dir].coords,profile:r.profiles[dir],stops:getStops(r,dir),start,seed,speedVariation:r.speedVariation,stopVariation:r.stopVariation});rowsTotal+=sim.rows.length;if(rowsTotal>1000000)throw Error('Route exceeds one million observations. Reduce trip counts or duration.');if(i+1<r[dir+'Count']&&sim.recordedDuration>=r.spacingHours*3600)throw Error('Same-direction trips overlap. Increase the repeat interval.');const filename='trip-'+String(++index).padStart(4,'0')+'.'+r.format;entries.push({filename,direction:dir,start,sim});if(index%5===0){onProgress(index);await new Promise(resolve=>setTimeout(resolve,0));}}return {route:structuredClone(r),entries,rowsTotal};}
function manifest(b){return {schemaVersion:1,source:'synthetic',generator:'LIGTAS Trip Studio 1.0',samplingIntervalSeconds:INTERVAL,timestampTimezone:'UTC',inputTimezone:'Asia/Manila',speedTimeAxis:'moving seconds; paused during explicit stops',interpolation:'linear speed; distance integrated over time',arrivalPolicy:'hold destination until the next ten-second sample',createdAt:new Date().toISOString(),route:b.route,recordings:b.entries.map(e=>({file:'recordings/'+e.filename,direction:e.direction,start:e.start,seed:e.sim.seed,speedFactor:e.sim.speedFactor,arrivalSeconds:e.sim.arrival,recordedSeconds:e.sim.recordedDuration,rows:e.sim.rows.length,stops:e.sim.events}))};}
async function zipBatches(batches,name){if(!window.JSZip)throw Error('ZIP library unavailable. Reload the page.');const zip=new JSZip();for(let b=0;b<batches.length;b++){const batch=batches[b],folder=zip.folder(String(b+1).padStart(2,'0')+'-'+slug(batch.route.name));folder.file('manifest.json',JSON.stringify(manifest(batch),null,2));folder.file('project.json',JSON.stringify({version:1,server:state.server,routes:[batch.route]},null,2));for(let i=0;i<batch.entries.length;i++){const e=batch.entries[i];folder.file('recordings/'+e.filename,encode(e.sim.rows,batch.route.format));if(i%10===0)await new Promise(resolve=>setTimeout(resolve,0));}}zip.file('README.txt','LIGTAS synthetic GPS recordings\n\nSimulated data for development and controlled replay, not commuter observations. Each file has timestamp, latitude and longitude at exact ten-second intervals. Timestamps use UTC (Z); departure inputs use Asia/Manila (UTC+08:00). Direction, seeds, road geometry, speeds and stop events are separate in the manifest. Speed is linearly interpolated over moving time; explicit stops pause that clock. The final speed continues until arrival, then the destination is held to the next sample. Use project.json to edit and reproduce each route.\n');download(await zip.generateAsync({type:'blob',compression:'DEFLATE',compressionOptions:{level:3}}),name);toast('ZIP downloaded · '+batches.reduce((s,b)=>s+b.entries.length,0)+' separate trip files.');}
async function busy(btn,fn){const label=btn.textContent;btn.disabled=true;btn.textContent='Preparing…';try{await fn();}catch(err){toast(err.message,true);}finally{btn.disabled=false;btn.textContent=label;}}
$('previewTrips').onclick=()=>busy($('previewTrips'),async()=>{stopPlayback();const r=structuredClone(current()),revision=JSON.stringify(r),batch=await generate(r,n=>$('previewTrips').textContent='Generating trip '+n+'…');if(r.id!==active||revision!==JSON.stringify(current()))throw Error('Route changed during generation. Generate again.');preview=batch;$('preview').hidden=false;$('previewSummary').textContent=`${batch.entries.length} files · ${batch.rowsTotal.toLocaleString()} observations · every 10 seconds · ${r.format.toUpperCase()}`;$('recordingSelect').innerHTML=batch.entries.map((e,i)=>`<option value="${i}">${e.filename}</option>`).join('');showRecording();$('preview').scrollIntoView({behavior:'smooth',block:'start'});});$('exportRoute').onclick=()=>busy($('exportRoute'),async()=>{const batch=await generate(structuredClone(current()));await zipBatches([batch],slug(batch.route.name)+'.zip');});$('exportAll').onclick=()=>busy($('exportAll'),async()=>{const batches=[];let total=0;for(const r of structuredClone(state.routes)){const batch=await generate(r);total+=batch.rowsTotal;if(total>2000000)throw Error('Project exceeds two million observations. Export routes separately.');batches.push(batch);}await zipBatches(batches,'ligtas-trips.zip');});$('downloadZip').onclick=()=>busy($('downloadZip'),async()=>{if(!preview)throw Error('Generate recordings first.');await zipBatches([preview],slug(preview.route.name)+'.zip');});
const selectedEntry=()=>preview?.entries[Number($('recordingSelect').value)||0];
function showRecording(){stopPlayback();const e=selectedEntry();if(!e)return;const rows=e.sim.rows,indexes=[...Array(Math.min(8,rows.length)).keys()];if(rows.length>8){if(rows.length>9)indexes.push(rows.length-2);indexes.push(rows.length-1);}$('previewRows').innerHTML=indexes.map(i=>`<tr><td>${rows[i].timestamp}</td><td>${rows[i].latitude.toFixed(7)}</td><td>${rows[i].longitude.toFixed(7)}</td></tr>`).join('');$('playhead').max=rows.length-1;$('playhead').value=0;showFrame();}
function showFrame(){const e=selectedEntry();if(!e)return;const i=Number($('playhead').value),row=e.sim.rows[i];if(map){if(!playMarker)playMarker=L.circleMarker([row.latitude,row.longitude],{radius:7,color:'#fff',weight:3,fillColor:'#dc7c2d',fillOpacity:1}).addTo(map);else playMarker.setLatLng([row.latitude,row.longitude]);}$('playStatus').textContent=`${row.timestamp} · sample ${i+1} / ${e.sim.rows.length} · ${row.latitude.toFixed(7)}, ${row.longitude.toFixed(7)} · ${e.direction==='outbound'?'Outbound':'Return'} preview`;}$('recordingSelect').onchange=showRecording;$('playhead').oninput=()=>{stopPlayback();showFrame();};$('playTrip').onclick=()=>{if(playTimer){stopPlayback();return;}if(!selectedEntry())return;if(Number($('playhead').value)>=Number($('playhead').max))$('playhead').value=0;$('map').scrollIntoView({behavior:'smooth',block:'center'});$('playTrip').textContent='Ⅱ Pause';playTimer=setInterval(()=>{const n=Number($('playhead').value)+1;if(n>Number($('playhead').max)){stopPlayback();return;}$('playhead').value=n;showFrame();},150);};$('downloadFile').onclick=()=>{const e=selectedEntry();if(e)download(encode(e.sim.rows,preview.route.format),e.filename,preview.route.format==='csv'?'text/csv':preview.route.format==='json'?'application/json':'application/gpx+xml');};

// Commit valid edits on input as well as blur, including programmatic input tools.
$('stops').addEventListener('input',e=>{const id=e.target.dataset.stopName??e.target.dataset.stopDuration;if(!id)return;const p=current().points.find(p=>p.id===id);if(e.target.dataset.stopName!==undefined)p.name=e.target.value;else{const n=e.target.valueAsNumber;if(!Number.isFinite(n)||n<0||n>7200)return;p.duration=n;}changed();});
$('speedPoints').addEventListener('input',e=>{const el=e.target,i=Number(el.dataset.time??el.dataset.speed),p=current().profiles[direction()],key=el.dataset.time!==undefined?'t':'v',n=el.valueAsNumber;if(!Number.isFinite(n))return;const next=p.map((a,j)=>j===i?{...a,[key]:n}:a);try{if(next.some(a=>a.t>7200))throw Error('Time out of range');normalizeProfile(next);p[i][key]=n;el.removeAttribute('aria-invalid');changed();renderGraph();}catch{el.setAttribute('aria-invalid','true');}});
for(const id of ['outboundCount','returnCount','outboundStart','returnStart','spacingHours','format','seed'])$(id).addEventListener('input',e=>{const r=current(),next={...r,[id]:['outboundStart','returnStart','format'].includes(id)?e.target.value:e.target.valueAsNumber};try{validateSettings(next);r[id]=next[id];e.target.removeAttribute('aria-invalid');changed();}catch{e.target.setAttribute('aria-invalid','true');}});
$('graphRange').addEventListener('input',e=>{const n=e.target.valueAsNumber;if(Number.isFinite(n)&&n>=60&&n<=7200){current().graphRange=n;save();renderGraph();}});
render();save();
